//! INPUT constraint metadata reflection over original attributes.
use super::*;
const MEMBERS:[&str;4]=["pattern","min","max","step"];
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=form method=post action='/submit'><input id=area name=q value=Seed><input id=neighbor value=neighbor></form></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://input-constraints.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn input_constraint_metadata_canonical_descriptors_and_once_dom_string_conversion(){for key in MEMBERS{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var key='{key}',x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,key);if(!a||!a.enumerable||!a.configurable||a.get.name!=='get '+key||a.set.name!=='set '+key||a.get.length!==0||a.set.length!==1||Object.hasOwn(x,key)||x[key]!=='')throw 'canonical constraint metadata';var calls=0;x[key]={{toString:function(){{calls++;return ' +2tail';}},valueOf:function(){{throw 'wrong hint';}}}};if(calls!==1||x[key]!==' +2tail'||x.getAttributeNS(null,key)!==' +2tail'||x.value!=='Seed'||x.defaultValue!=='Seed')throw 'exact metadata';"#));}}
#[test]
fn input_constraint_metadata_native_inert_namespace_raw_utf16_and_missing(){for key in MEMBERS{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var key='{key}',x=document.getElementById('area'),owner=new Document(),inert=owner.createElementNS('http://www.w3.org/1999/xhtml','input');for(var target of [x,inert]){{target.setAttributeNS('urn:other',key,'foreign');target.setAttributeNS(null,key.toUpperCase(),'upper');if(target[key]!=='')throw 'namespace alias';for(var text of ['', 'any','INVALID','-3.5','2026-11-25','\ud800x\udc00','a\u0000b']){{target[key]=text;if(target[key]!==text||target.getAttributeNS(null,key)!==text)throw 'raw metadata';}}if(target.getAttributeNS('urn:other',key)!=='foreign'||target.getAttributeNS(null,key.toUpperCase())!=='upper')throw 'namespace isolation';target.removeAttributeNS(null,key);if(target[key]!=='')throw 'missing metadata';}}"#));}}

#[test]
fn input_constraint_metadata_attribute_producers_identity_observers_and_native_editor_isolation(){for key in MEMBERS{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var key='{key}',x=document.getElementById('area');x.value='dirty';x[key]='seed';var attribute=x.getAttributeNodeNS(null,key),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true,attributeFilter:[key]}});"));let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=3;e.anchor=1;e.offset=2;}for source in ["x.setAttribute(key,'raw\\ud800');","x.setAttributeNS(null,key,'raw\\ud800');","attribute.value='raw\\ud800';","attribute.nodeValue='raw\\ud800';","attribute.textContent='raw\\ud800';"]{p.begin_job();run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r#"var records=watch.takeRecords();if(x[key]!=='raw\ud800'||x.getAttributeNodeNS(null,key)!==attribute||records.length!==1||records[0].target!==x||records[0].attributeName!==key||x.value!=='dirty'||x.defaultValue!=='Seed')throw 'metadata producer';"#);let c=&f.controls[&n];assert_eq!((c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value),(3,1,2,true));}run(&mut d,&mut f,&mut p,"var replacement=document.createAttribute(key);replacement.value='replacement';x.setAttributeNodeNS(replacement);if(x[key]!=='replacement'||attribute.ownerElement!==null||replacement.ownerElement!==x)throw 'replacement metadata';");}}
#[test]
fn input_constraint_metadata_dom_string_matrix_reentrancy_and_abrupt_effects(){for key in MEMBERS{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var key='{key}',x=document.getElementById('area');for(var pair of [[null,'null'],[undefined,'undefined'],[false,'false'],[42,'42'],[BigInt(7),'7']]){{x[key]=pair[0];if(x[key]!==pair[1])throw 'DOMString conversion';}}var calls=0;x[key]={{toString:function(){{calls++;x[key]='inner';return 'outer';}}}};if(calls!==1||x[key]!=='outer')throw 'reentrant conversion';var marker={{}};try{{x[key]={{toString:function(){{calls++;x.setAttribute('data-side','kept');throw marker;}}}};throw 'missing abrupt';}}catch(e){{if(e!==marker)throw e;}}try{{x[key]=Symbol('bad');throw 'missing symbol refusal';}}catch(e){{if(!(e instanceof TypeError))throw e;}}if(calls!==2||x[key]!=='outer'||x.getAttribute('data-side')!=='kept'||x.value!=='Seed')throw 'abrupt effects';"#));}}
#[test]
fn input_constraint_metadata_brand_precedes_conversion_saved_authority_and_overrides(){for key in MEMBERS{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var key='{key}',x=document.getElementById('area'),P=HTMLInputElement.prototype,a=Object.getOwnPropertyDescriptor(P,key),calls=0;for(var bad of [{{}},document,document.createElement('textarea'),Object.create(P)]){{try{{a.set.call(bad,{{toString:function(){{calls++;return 'bad';}}}});throw 'missing brand';}}catch(e){{if(!(e instanceof TypeError))throw e;}}}}if(calls||x[key]!=='')throw 'brand converted';Object.defineProperty(P,key,{{get:function(){{return 'author';}},set:function(v){{this.setAttribute('data-author',v);}},configurable:true}});x[key]='override';a.set.call(x,'saved');if(x[key]!=='author'||a.get.call(x)!=='saved'||x.getAttribute('data-author')!=='override')throw 'saved authority';delete P[key];if(x[key]!==undefined)throw 'deleted hidden member';Object.defineProperty(P,key,a);var C=HTMLInputElement;delete window.HTMLInputElement;if(!(x instanceof C)||a.get.call(x)!=='saved')throw 'saved roots';"#));}}
#[test]
fn input_constraint_metadata_fragment_clone_detach_and_actual_post_isolation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.createElement('div');host.innerHTML='<input id=fresh name=fresh pattern="[A-Z]+" min=" +2tail" max="-4" step="any" value=source>';document.getElementById('form').appendChild(host);var x=host.firstChild;x.value='edited';var copy=x.cloneNode(true);if(copy.pattern!=='[A-Z]+'||copy.min!==' +2tail'||copy.max!=='-4'||copy.step!=='any'||copy.value!=='edited'||copy.defaultValue!=='source')throw 'clone metadata';copy.pattern='copy';copy.min='0';copy.max='10';copy.step='2';if(x.pattern!=='[A-Z]+'||x.min!==' +2tail'||x.max!=='-4'||x.step!=='any')throw 'clone alias';host.removeChild(x);x.step='3';document.getElementById('form').appendChild(x);if(x.form!==document.getElementById('form')||x.value!=='edited'||x.step!=='3')throw 'reconnected metadata';if(!x.validity.patternMismatch)throw 'active pattern constraint';document.getElementById('form').noValidate=true;"#);let owner=(0..d.nodes.len()).find(|n|d.attr(*n,"id")==Some("form")).unwrap();let l=crate::navigation::address("https://input-constraints.test/source",&crate::navigation::Location::home()).unwrap();let result=f.submit_request(&d,owner,None,&l,&l).unwrap();let crate::http::Request::FormPost{body,..}=result.request else{panic!("POST")};assert_eq!(String::from_utf8(body).unwrap(),"q=Seed&fresh=edited");}
#[test]
fn input_constraint_metadata_resource_refusal_preserves_dom_editor_and_recovers(){for key in MEMBERS{for mode in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var key='{key}',x=document.getElementById('area');x.value='dirty';"));let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("input")};let n=*f.controls.keys().find(|n|d.attr(**n,"id")==Some("area")).unwrap();let nodes=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);let capture=|f:&Forms|{let c=&f.controls[&n];(c.max_length,c.value.text(),c.value.cursor,c.value.anchor,c.value.offset,c.dirty_value)};let before=capture(&f);let retained=p.state.retained_limit;p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let mut bridge=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};let value=Value::String("growing metadata".repeat(64));let result=match key{"pattern"=>bridge.input_pattern_set(object,&value),"min"=>bridge.input_min_set(object,&value),"max"=>bridge.input_max_set(object,&value),_=>bridge.input_step_set(object,&value)};assert!(result.is_err());assert_eq!(format!("{:?}",d.nodes),nodes);assert_eq!((p.state.retained,p.state.dom_commits),state);assert_eq!(capture(&f),before);p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"x[key]='recovered';if(x[key]!=='recovered'||x.value!=='dirty')throw 'fresh metadata recovery';");}}}
#[test]
fn input_constraint_metadata_saved_child_origin_refuses_before_conversion_and_recovers(){for key in MEMBERS{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var key='{key}',x=document.getElementById('area');x[key]='seed';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var a=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLInputElement.prototype,key),calls=0;if(a.get.call(x)!=='seed')throw 'same origin getter';"));p.set_location(&crate::navigation::address("https://foreign-input-constraints.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);p.begin_job();let e=p.runtime.execute("a.set.call(x,{toString:function(){calls++;return 'denied';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);p.set_location(&crate::navigation::address("https://input-constraints.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||x[key]!=='seed')throw 'origin converted';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'origin recovery';");}}
